mapper.sql:
EXISTS (SELECT 1 FROM o_goods_inventory z
  WHERE z.sku_id=s.id AND COALESCE(z.is_delete,0)=0 AND z.stock_status=1
  AND z.merchant_id=#{merchantId}
  AND z.shop_id=#{shopId}
  AND z.warehouse_id=#{warehouseId}
  GROUP BY z.warehouse_id,z.merchant_id,z.shop_id
  HAVING SUM(z.available_quantity)<=0)

mapper.select:
SELECT id, goods_id, goods_num, sku_id, sku_code, goods_name, sku_name,
       quantity, locked_quantity, available_quantity, warehouse_id, merchant_id,
       shop_id, stock_status, update_time
FROM o_goods_inventory
WHERE sku_id = #{skuId} AND COALESCE(is_delete, 0) = 0
AND warehouse_id = #{warehouseId}
AND merchant_id = #{merchantId}
AND shop_id = #{shopId}
ORDER BY warehouse_id, merchant_id, shop_id, id
LIMIT 200

SELECT sku_id AS skuId, warehouse_id AS warehouseId, merchant_id AS merchantId,
       shop_id AS shopId, SUM(available_quantity) AS availableQuantity
FROM o_goods_inventory
WHERE COALESCE(is_delete,0)=0 AND stock_status=1 AND sku_id IN
#{id}
AND merchant_id=#{merchantId}
AND shop_id=#{shopId}
AND warehouse_id=#{warehouseId}
GROUP BY sku_id,warehouse_id,merchant_id,shop_id
HAVING SUM(available_quantity)<=0
ORDER BY sku_id,warehouse_id,merchant_id,shop_id LIMIT 1001

SELECT i.spec_id AS skuId, COUNT(DISTINCT p.id) AS openPurchaseOrders
FROM erp_purchase_order p JOIN erp_purchase_order_item i ON i.order_id=p.id
WHERE i.spec_id IN
#{id}
  AND COALESCE(i.is_delete,0)=0 AND i.quantity>0
  AND i.merchant_id=p.merchant_id AND i.shop_id=p.shop_id
  AND p.status IN (1,2,101,102)
  AND p.merchant_id=#{merchantId}
  AND p.shop_id=#{shopId}
GROUP BY i.spec_id

SELECT i.goods_sku_id AS skuId, SUM(i.quantity) AS sales30Days
FROM o_order_item i JOIN o_order o ON o.id = i.order_id
WHERE i.goods_sku_id IN
#{id}
  AND o.order_time >= #{start} AND o.order_time < #{end}
  AND o.payment > 0 AND o.order_status IN (1, 2, 3, 101)
  AND o.merchant_id = #{merchantId}
  AND o.shop_id = #{shopId}
GROUP BY i.goods_sku_id

SELECT COALESCE(SUM(i.quantity), 0)
FROM o_order_item i JOIN o_order o ON o.id = i.order_id
WHERE i.goods_sku_id = #{skuId}
  AND o.order_time >= #{start} AND o.order_time < #{end}
  AND o.payment > 0 AND o.order_status IN (1, 2, 3, 101)
  AND o.merchant_id = #{merchantId}
  AND o.shop_id = #{shopId}
